import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync,readdirSync} from 'node:fs';
const dir='database/migrations';const names=readdirSync(dir).filter((x:string)=>x.endsWith('.sql')).sort();const sql=names.map((x:string)=>readFileSync(`${dir}/${x}`,'utf8')).join('\n');
test('production package omits conflicting 009/010',()=>{assert.equal(names.some((x:string)=>x.startsWith('009_')),false);assert.equal(names.some((x:string)=>x.startsWith('010_')),false);assert.equal(names.some((x:string)=>x.startsWith('011_')),true)});
for(const [name,re] of Object.entries({postgis:/CREATE EXTENSION IF NOT EXISTS postgis/,certifiedOnly:/zsl\.certified_release_records/,zipNotZcta:/CREATE TABLE IF NOT EXISTS zsl\.postal_codes/,zctaSeparate:/CREATE TABLE IF NOT EXISTS zsl\.zctas/,multiParent:/CREATE TABLE IF NOT EXISTS zsl\.location_relationships/,spatialIndex:/USING gist\(point\)/,r1bNoDirectMutation:/r1b_location_sync_proposals/,certGuard:/zsl2_certification_guard/,immutable:/zsl2_prevent_mutation/,publicRevoke:/REVOKE ALL ON zsl\.locations/,runScoped:/zsl2_location_run_memberships/,authorityEvents:/zsl2_authority_events/,rbac:/CREATE ROLE zsl2_reader/,perf:/zsl2_performance_measurements/,territory:/zsl2_territorial_pending_evidence_v214/,territorialAreaEvidence:/zsl2_postal_territorial_area_evidence_v214/,authorityDecision:/zsl2_zsl1_authority_decisions_v214/}))test(name,()=>assert.match(sql,re as RegExp));
test('R1B remains proposal-only',()=>assert.doesNotMatch(sql,/INSERT\s+INTO\s+retail\.search_locations/i));
